#include <stdio.h>
#include <stdlib.h>

#define MAX_N 64

static long value[MAX_N];
static int next_idx[MAX_N];
static int head = -1;          // index of first element, -1 = empty list
static int used = 0;           // number of elements stored

int main(int argc, char *argv[])
{
    // Build a sorted linked list (ascending) from the command‑line arguments.
    for (int i = 1; i < argc && used < MAX_N; ++i) {
        char *endptr;
        long v = strtol(argv[i], &endptr, 10);
        // ignore non‑numeric arguments (behaviour of original program)
        (void)endptr; // silence unused warning
        // Insert v into the list keeping it sorted.
        int new_idx = used;
        value[new_idx] = v;
        next_idx[new_idx] = -1;
        if (head == -1 || value[head] > v) {
            // Insert at the front.
            next_idx[new_idx] = head;
            head = new_idx;
        } else {
            // Find the node after which to insert.
            int cur = head;
            while (next_idx[cur] != -1 && value[next_idx[cur]] <= v) {
                cur = next_idx[cur];
            }
            next_idx[new_idx] = next_idx[cur];
            next_idx[cur] = new_idx;
        }
        ++used;
    }

    if (used == 0) {
        puts("EMPTY");
        return 0;
    }

    // Print the list in order, values separated by a single space.
    for (int idx = head; idx != -1; idx = next_idx[idx]) {
        printf("%ld", value[idx]);
        if (next_idx[idx] != -1)
            putchar(' ');
    }
    putchar('\n');
    return 0;
}
